/** Real separate NOLOGIN identities, actual PostgreSQL ACLs, synthetic signed reviews only. */
@EnabledIfEnvironmentVariable(named="EODIISSEO_LOCAL_DB_TESTS",matches="true")
@TestInstance(TestInstance.Lifecycle.PER_CLASS) @Timeout(90)
class CollectionAssurancePostgresTest {
    final CollectionOperationsPostgresTest f=new CollectionOperationsPostgresTest();
    JdbcCollectionAssurance store;KeyPair pair;Verifier verifier;String schema,worker,opsRole,migration,relay;DataSource ds;
    static final String H="a".repeat(64);boolean stopped=true,restart=true;String currentInventory=H;
    @BeforeAll void open()throws Exception{
        if(!"jdbc:postgresql://127.0.0.1:55433/postgres".equals(System.getenv("EODIISSEO_AUDIT_JDBC_URL"))||!"true".equals(System.getenv("EODIISSEO_AUDIT_DISPOSABLE")))throw new IllegalStateException("Approved disposable only");
        f.admin=new JdbcTemplate(new DriverManagerDataSource(System.getenv("EODIISSEO_AUDIT_JDBC_URL"),"eodiisseo_audit",""));String suffix=UUID.randomUUID().toString().replace("-","");f.database="collection4b2_"+suffix;schema="cs_"+suffix;worker="c4b2_"+suffix+"_w";opsRole="c4b2_"+suffix+"_o";migration="c4b2_"+suffix+"_m";relay="c4b2_"+suffix+"_r";f.admin.execute("create database "+f.database);
        ds=new DriverManagerDataSource("jdbc:postgresql://127.0.0.1:55433/"+f.database,"eodiisseo_audit","");f.sql=new JdbcTemplate(ds);
        Flyway.configure().dataSource(ds).locations("classpath:db/migration","classpath:db/owned-runtime","classpath:db/collection-executor","classpath:db/collection-projection","classpath:db/collection-operations","classpath:db/collection-cutover").load().migrate();
        assertThrows(IllegalStateException.class,()->JdbcCollectionAssurance.requireSchema(f.sql));String before=f.sql.queryForObject("select collection_policy_fingerprint()",String.class);
        Flyway.configure().dataSource(ds).locations(locations()).load().migrate();Flyway.configure().dataSource(ds).locations(locations()).load().validate();assertEquals(before,f.sql.queryForObject("select collection_policy_fingerprint()",String.class));
        f.sql.execute("create table projection_tx_probe(id uuid primary key)");f.app=new AnnotationConfigApplicationContext();f.app.getEnvironment().setActiveProfiles("collection-projection-audit-only");f.app.registerBean("dataSource",DataSource.class,()->ds);f.app.register(OfficialCollectionProjectionPostgresTest.Config.class);f.app.refresh();f.manager=f.app.getBean("transactionManager",JpaTransactionManager.class);
        pair=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();verifier=new Verifier(Map.of("SYNTHETIC_REVIEWER",new TrustRoot(pair.getPublic(),EnumSet.allOf(Kind.class),true)));
        for(String role:List.of(worker,opsRole,migration,relay))f.sql.execute("create role "+role+" nologin noinherit nosuperuser nocreatedb nocreaterole noreplication nobypassrls");
        f.sql.execute("revoke create,temporary on database "+f.database+" from public");f.sql.execute("create schema "+schema+" authorization "+migration);
        f.sql.execute("create table "+schema+".secure_history(id int primary key,body text)");f.sql.execute("alter table "+schema+".secure_history owner to "+migration);f.sql.execute("insert into "+schema+".secure_history values(1,'SYNTHETIC body')");
        f.sql.execute("create function "+schema+".history_guard() returns trigger language plpgsql as $$ begin raise exception 'SYNTHETIC immutable'; end $$");f.sql.execute("alter function "+schema+".history_guard() owner to "+migration);f.sql.execute("create trigger history_guard before update or delete on "+schema+".secure_history for each row execute function "+schema+".history_guard()");
        f.sql.execute("create view "+schema+".collection_archive_metadata as select id from "+schema+".secure_history");f.sql.execute("alter view "+schema+".collection_archive_metadata owner to "+migration);
        f.sql.execute("create table "+schema+".approval_input(id int primary key,digest text)");f.sql.execute("alter table "+schema+".approval_input owner to "+migration);
        for(String role:List.of(worker,opsRole)){f.sql.execute("grant usage on schema "+schema+" to "+role);f.sql.execute("grant select on "+schema+".collection_archive_metadata to "+role);}
        f.sql.execute("grant insert,select on "+schema+".approval_input to "+opsRole);
        System.out.println("STAGE4B2_POSTGRES_VERSION="+f.sql.queryForObject("show server_version",String.class));
    }
    static String[] locations(){return new String[]{"classpath:db/migration","classpath:db/owned-runtime","classpath:db/collection-executor","classpath:db/collection-projection","classpath:db/collection-operations","classpath:db/collection-cutover","classpath:db/collection-assurance"};}
    @AfterAll void close(){if(f.app!=null)f.app.close();if(f.database!=null&&f.database.matches("collection4b2_[a-f0-9]{32}"))f.admin.execute("drop database "+f.database);if(f.admin!=null)for(String role:Arrays.asList(worker,opsRole,migration,relay))if(role!=null&&role.matches("c4b2_[a-f0-9]{32}_[womr]"))f.admin.execute("drop role if exists "+role);}
    @BeforeEach void fixture(){
        f.sql.execute("truncate collection_assurance_artifact,collection_assurance_revocation,collection_transition_review,collection_component_approval,collection_operation_approval,collection_approval_revocation,collection_resolution_detail,collection_run,member cascade");
        f.sql.update("insert into collection_cutover_barrier values(true,'LEGACY',0,null,clock_timestamp())");
        f.ops=f.member(true);f.evidence=new CollectionOperationsPostgresTest.Witness();f.service=f.service(CollectionOperationMode.DISPOSABLE_AUDIT,f.evidence);store=new JdbcCollectionAssurance(f.sql,f.manager,f.service,CollectionOperationMode.DISPOSABLE_AUDIT,verifier);stopped=true;restart=true;currentInventory=H;
    }
    Map<String,Object> payload(Kind kind){var p=new LinkedHashMap<String,Object>();switch(kind){
        case FLEET -> {for(String k:List.of("inventory_sha256","deployment_sha256","restart_policy_sha256","pending_requests_sha256"))p.put(k,H);for(String k:List.of("stopped","restart_blocked","schedulers_disabled","complete_inventory"))p.put(k,true);p.put("instance_ids",List.of("SYNTHETIC:VM_A"));p.put("observation_ttl_seconds",120);}
        case SENDER -> {for(String k:List.of("implementation_sha256","runtime_sha256","endpoint_sha256"))p.put(k,H);for(String k:List.of("one_attempt","no_redirect","no_proxy","no_secret_logging","bounded_body","bounded_timeout"))p.put(k,true);}
        case ARCHIVE -> {p.put("retention_seconds",3600);for(String k:List.of("acl_sha256","privacy_review_sha256","secret_detector_sha256","expiry_plan_sha256","audit_retention_sha256","receipt_fk_plan_sha256"))p.put(k,H);p.put("secret_detector_sha256",new ReviewedRawPrivacyDetector(Set.of("synthetic"),H).fingerprint());}
        case API -> {for(String k:List.of("document_sha256","response_contract_sha256","route_sha256"))p.put(k,H);for(String k:List.of("bounded_range","stable_snapshot","incremental","empty_result"))p.put(k,true);}
        case PROJECTION -> {for(String k:List.of("contract_sha256","normalizer_sha256","mapping_sha256"))p.put(k,H);p.put("initial_date","2026-11-01");p.put("canonical_source",UUID.randomUUID().toString());p.put("incident_link_verified",true);p.put("coverage_allowed",true);p.put("empty_allowed",false);}
        case DOMAIN_POLICY -> {for(String k:List.of("manifest_sha256","normalizer_sha256","verification_rules_sha256"))p.put(k,H);}
        default -> throw new IllegalArgumentException("Test payload explicitly required");}return p;}
    Artifact signed(Kind kind,String scope,Map<String,Object> payload)throws Exception{var a=new Artifact(UUID.randomUUID(),kind,scope,"SYNTHETIC-v1","SYNTHETIC_REVIEWER","SYNTHETIC:SIGNED_REVIEW",payload,Instant.now().minusSeconds(60),Instant.now().plusSeconds(600),true,new byte[0]);var sig=Signature.getInstance("Ed25519");sig.initSign(pair.getPrivate());sig.update(a.signingBytes());return new Artifact(a.id(),a.kind(),a.scope(),a.version(),a.issuer(),a.reference(),a.payload(),a.from(),a.until(),a.synthetic(),sig.sign());}
    Artifact save(Kind kind,String scope)throws Exception{var a=signed(kind,scope,payload(kind));store.submit(f.ops,a);return a;}
    VerifiedCollectionOperationalEvidence adapter(){CollectionFleetEvidencePort fleet=()->Optional.of(new CollectionFleetEvidencePort.Observation(Set.of("SYNTHETIC:VM_A"),currentInventory,H,H,H,stopped,restart,true,true,Instant.now().minusSeconds(1),Instant.now().plusSeconds(60),true));return new VerifiedCollectionOperationalEvidence(store,fleet,new VerifiedCollectionOperationalEvidence.SenderBinding((key,r)->new com.disasterinfo.eodiisseo.collection.execution.CollectionProviderPort.Reply(200,new byte[0],Duration.ZERO),H,H,H,true),Set.of(),Clock.systemUTC(),new ReviewedRawPrivacyDetector(Set.of("synthetic"),H));}
    CollectionDatabasePrivilegeInspector.Policy policy(){return new CollectionDatabasePrivilegeInspector.Policy(worker,opsRole,migration,migration,schema);}
    @Test void signedEvidenceRoundTripsAndRevokes()throws Exception{var a=save(Kind.FLEET,"GLOBAL");assertEquals(a.id(),store.active(Kind.FLEET,"GLOBAL").orElseThrow().id());assertEquals(a.digest(),store.active(Kind.FLEET,"GLOBAL").orElseThrow().digest());}
    @Test void activeEvidenceRevocationIsImmediate()throws Exception{var a=save(Kind.FLEET,"GLOBAL");store.revoke(f.ops,a.id(),"SYNTHETIC:REVOKED");assertTrue(store.active(Kind.FLEET,"GLOBAL").isEmpty());assertThrows(RuntimeException.class,()->store.revoke(f.ops,a.id(),"SYNTHETIC:TWICE"));}
    @Test void alteredPayloadDoesNotReuseApproval()throws Exception{var a=signed(Kind.FLEET,"GLOBAL",payload(Kind.FLEET));var p=new HashMap<>(a.payload());p.put("stopped",false);var changed=new Artifact(a.id(),a.kind(),a.scope(),a.version(),a.issuer(),a.reference(),p,a.from(),a.until(),true,a.signature());assertThrows(RuntimeException.class,()->store.submit(f.ops,changed));assertEquals(0,f.count("collection_assurance_artifact"));}
    @Test void syntheticRootCannotBeRelabeledAsProduction()throws Exception{var a=signed(Kind.API,"KMA_PORTAL_EQK_MSG",payload(Kind.API));var relabeled=new Artifact(a.id(),a.kind(),a.scope(),a.version(),a.issuer(),a.reference(),a.payload(),a.from(),a.until(),false,a.signature());assertFalse(verifier.verify(a,CollectionOperationMode.PRODUCTION,Instant.now()));assertFalse(verifier.verify(relabeled,CollectionOperationMode.PRODUCTION,Instant.now()));}
    @Test void duplicateVersionCannotOverwrite()throws Exception{var a=save(Kind.FLEET,"GLOBAL");assertThrows(RuntimeException.class,()->store.submit(f.ops,a));assertThrows(RuntimeException.class,()->f.sql.update("update collection_assurance_artifact set reference='SYNTHETIC:ALTERED'"));}
    @Test void noOpsRoleOrRevokedSessionCannotSubmit()throws Exception{var a=signed(Kind.FLEET,"GLOBAL",payload(Kind.FLEET));f.sql.update("delete from member_role where member_id=?",f.ops.memberId());assertThrows(RuntimeException.class,()->store.submit(f.ops,a));assertEquals(0,f.count("collection_assurance_artifact"));}
    @Test void fleetInventoryAndRestartChangesInvalidateProof()throws Exception{save(Kind.FLEET,"GLOBAL");var port=adapter();assertTrue(port.legacyWorkersStopped());restart=false;assertFalse(port.legacyWorkersStopped());restart=true;currentInventory="b".repeat(64);assertFalse(port.legacyWorkersStopped());}
    @Test void senderAndArchiveNeedExactSignedConfiguration()throws Exception{save(Kind.FLEET,"GLOBAL");assertNull(adapter().transport());save(Kind.SENDER,"GLOBAL");assertNotNull(adapter().transport());assertNull(adapter().archivePolicy());save(Kind.ARCHIVE,"GLOBAL");assertEquals(Duration.ofHours(1),adapter().archivePolicy().retention());}
    @Test void apiAndProjectionWithdrawalBlocksAdmission()throws Exception{var a=save(Kind.API,"KMA_PORTAL_EQK_MSG");var p=save(Kind.PROJECTION,"KMA_PORTAL_EQK_MSG");var assignment=new CollectionOwnership.Assignment(UUID.randomUUID(),"KMA_EARTHQUAKE",UUID.randomUUID(),"KMA_PORTAL_EQK_MSG","SYNTHETIC-quota",1,"COMMON_COLLECTION_V1","SYNTHETIC ref",true);var claim=new CollectionOwnership.Claim(UUID.randomUUID(),UUID.randomUUID(),assignment,"LIVE",1);var admission=new ReviewedProjectionAdmission(store,H);assertTrue(admission.resolve(claim,LocalDate.of(2026,11,1),LocalDate.of(2026,11,1),Instant.now()).orElseThrow().synthetic());store.revoke(f.ops,p.id(),"SYNTHETIC:REVOKE_PROJECTION");assertTrue(admission.resolve(claim,LocalDate.of(2026,11,1),LocalDate.of(2026,11,1),Instant.now()).isEmpty());}
    @Test void allRealApiContractsRemainBlocked(){var c=new CollectionOfficialAdmissionCatalog();assertEquals(7,c.status().size());assertTrue(c.status().keySet().stream().noneMatch(c::productionAdmissible));}
    @Test void immutableBodyAndReceiptPreventUnapprovedCleanup()throws Exception{var a=save(Kind.ARCHIVE,"GLOBAL");var plan=new CollectionArchiveLifecycle(store).plan(Instant.now().minusSeconds(7200),Instant.now(),true,true);assertTrue(plan.policyApproved());assertFalse(plan.deleteAllowed());assertTrue(plan.blockers().contains("IMMUTABLE_BODY_SPLIT_OR_ERASURE_PROTOCOL_REQUIRED"));}
    @Test void approvalRevocationWaitsForEvidenceUseTransaction()throws Exception{var a=save(Kind.FLEET,"GLOBAL");var entered=new CountDownLatch(1);var release=new CountDownLatch(1);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var use=pool.submit(()->store.stable(v->{assertTrue(v.find(Kind.FLEET,"GLOBAL").isPresent());entered.countDown();try{if(!release.await(10,TimeUnit.SECONDS))throw new IllegalStateException("SYNTHETIC wait");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}return true;}));assertTrue(entered.await(5,TimeUnit.SECONDS));var revoke=pool.submit(()->{store.revoke(f.ops,a.id(),"SYNTHETIC:CONCURRENT_REVOKE");return true;});try{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);boolean waiting=false;while(System.nanoTime()<end){if(f.sql.queryForObject("select count(*) from pg_stat_activity where datname=current_database() and wait_event_type='Lock'",Long.class)>0){waiting=true;break;}Thread.sleep(10);}assertTrue(waiting);}finally{release.countDown();}assertTrue(use.get(5,TimeUnit.SECONDS));assertTrue(revoke.get(5,TimeUnit.SECONDS));}assertTrue(store.active(Kind.FLEET,"GLOBAL").isEmpty());}
    interface SqlAction{void run(Statement statement)throws Exception;}
    void as(String role,SqlAction action)throws Exception{try(var c=ds.getConnection();var s=c.createStatement()){s.execute("set session authorization "+role);action.run(s);}}
    @Test void safeSeparatedRolesPassInspection(){var r=new CollectionDatabasePrivilegeInspector(f.sql).inspect(policy());assertEquals(List.of(),r.blockers());assertTrue(r.safe());}
    @Test void workerCannotDdlTriggerTruncateReadRawOrEscalate()throws Exception{as(worker,s->{assertThrows(SQLException.class,()->s.execute("create table "+schema+".forbidden(id int)"));assertThrows(SQLException.class,()->s.execute("alter table "+schema+".secure_history disable trigger all"));assertThrows(SQLException.class,()->s.execute("truncate "+schema+".secure_history"));assertThrows(SQLException.class,()->s.execute("select body from "+schema+".secure_history"));assertThrows(SQLException.class,()->s.execute("set role "+migration));assertThrows(SQLException.class,()->s.execute("set role "+opsRole));assertTrue(s.execute("select id from "+schema+".collection_archive_metadata"));});}
    @Test void opsCanSubmitMetadataButCannotMutateHistory()throws Exception{as(opsRole,s->{assertEquals(1,s.executeUpdate("insert into "+schema+".approval_input values("+Math.abs(UUID.randomUUID().hashCode())+",'SYNTHETIC digest')"));assertThrows(SQLException.class,()->s.execute("update "+schema+".secure_history set body='changed'"));assertThrows(SQLException.class,()->s.execute("drop trigger history_guard on "+schema+".secure_history"));assertThrows(SQLException.class,()->s.execute("set role "+migration));});}
    @Test void migrationOwnsSchemaAndWorkerOwnershipIsRejected()throws Exception{as(migration,s->{s.execute("create table "+schema+".migration_probe(id int)");s.execute("drop table "+schema+".migration_probe");});f.sql.execute("grant "+migration+" to "+worker);try{assertFalse(new CollectionDatabasePrivilegeInspector(f.sql).inspect(policy()).safe());}finally{f.sql.execute("revoke "+migration+" from "+worker);}}
    @Test void grantChangeInvalidatesAclFingerprint(){var inspector=new CollectionDatabasePrivilegeInspector(f.sql);var before=inspector.inspect(policy());f.sql.execute("grant update on "+schema+".secure_history to "+worker);try{var after=inspector.inspect(policy());assertFalse(after.safe());assertNotEquals(before.fingerprint(),after.fingerprint());}finally{f.sql.execute("revoke update on "+schema+".secure_history from "+worker);}}
    @Test void anySettableRoleMembershipIsRejectedEvenWithNoInherit(){f.sql.execute("grant "+relay+" to "+worker);try{assertTrue(new CollectionDatabasePrivilegeInspector(f.sql).inspect(policy()).blockers().stream().anyMatch(s->s.startsWith("UNAPPROVED_TRANSITIVE_ROLE_MEMBERSHIP")));}finally{f.sql.execute("revoke "+relay+" from "+worker);}}
    @Test void columnOnlyGrantCannotBypassRawReadPolicy(){var inspector=new CollectionDatabasePrivilegeInspector(f.sql);String before=inspector.inspect(policy()).fingerprint();f.sql.execute("grant select(body) on "+schema+".secure_history to "+worker);try{var result=inspector.inspect(policy());assertFalse(result.safe());assertNotEquals(before,result.fingerprint());assertTrue(result.blockers().stream().anyMatch(s->s.startsWith("SENSITIVE_COLUMN_READ")));}finally{f.sql.execute("revoke select(body) on "+schema+".secure_history from "+worker);}}
    @Test void signedQuotaBindsScopeWindowAndNumericLimits()throws Exception{Instant start=Instant.now().minusSeconds(60).truncatedTo(java.time.temporal.ChronoUnit.MICROS),end=start.plusSeconds(600);String scope="SYNTHETIC-shared-quota";var data=Map.<String,Object>of("quota_scope_id",scope,"starts_at",start.toString(),"ends_at",end.toString(),"request_limit",7,"min_interval_ms",250,"provider_quota_sha256",H);var a=signed(Kind.QUOTA,"QUOTA:"+CollectionAssurance.hash(scope).toUpperCase(Locale.ROOT),data);store.submit(f.ops,a);assertTrue(adapter().quotaApproved(scope,start,end,7,250,a.reference()));assertFalse(adapter().quotaApproved(scope,start,end,8,250,a.reference()));store.revoke(f.ops,a.id(),"SYNTHETIC:QUOTA_WITHDRAWN");assertFalse(adapter().quotaApproved(scope,start,end,7,250,a.reference()));}
    @Test void revokedOpsSessionCannotImportEvenValidSignature()throws Exception{var a=signed(Kind.FLEET,"GLOBAL",payload(Kind.FLEET));f.sql.update("update auth_session set revoked_at=now() where session_id=?",f.ops.sessionId());assertThrows(RuntimeException.class,()->store.submit(f.ops,a));assertEquals(0,f.count("collection_assurance_artifact"));}
    @Test void syntheticAdapterCannotSatisfyProductionReadiness()throws Exception{save(Kind.FLEET,"GLOBAL");assertTrue(adapter().productionBlockers(f.sql,List.of()).contains("AUDIT_ASSURANCE_ADAPTER_NOT_PRODUCTION"));assertTrue(adapter().productionBlockers(f.sql,List.of()).contains("PRODUCTION_BARRIER_NOT_INSTALLED_AUDIT_1005_IS_NOT_PRODUCTION"));}
    @Test void unreviewedDefinerFunctionIsRejected(){f.sql.execute("create function "+schema+".unreviewed_definer() returns integer language sql security definer as 'select 1'");try{assertTrue(new CollectionDatabasePrivilegeInspector(f.sql).inspect(policy()).blockers().contains("UNREVIEWED_DEFINER_EXECUTION"));}finally{f.sql.execute("drop function "+schema+".unreviewed_definer()");}}
}